import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

@Controller('api/v1')
export class FnSfr01904Controller {
  @Get('/annual-leave-histories')
  async listAnnualLeaveHistories(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const q = checks.queryOf(req.query) as Record<string, unknown>;
    const text = (name: string): string | null => {
      const v = q[name];
      if (v === undefined || v === null || v === '') {
        return null;
      }
      return String(v);
    };
    const pageText = text('page');
    const sizeText = text('size');
    const page = pageText === null ? 0 : Number(pageText);
    const size = sizeText === null ? DEFAULT_SIZE : Number(sizeText);
    if (!Number.isInteger(page) || page < 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호가 올바르지 않습니다.');
    }
    if (!Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기가 올바르지 않습니다.');
    }
    const limit = Math.min(size, MAX_SIZE);
    const startDate = text('startDate');
    const endDate = text('endDate');
    const employeeId = text('employeeId');
    if (startDate !== null && !DATE_PATTERN.test(startDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 시작일 형식이 올바르지 않습니다.');
    }
    if (endDate !== null && !DATE_PATTERN.test(endDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 종료일 형식이 올바르지 않습니다.');
    }
    if (employeeId !== null && !/^\d+$/.test(employeeId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '대상 임직원이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      let where = 'WHERE 1 = 1';
      const params: Record<string, unknown> = {};
      if (startDate !== null) {
        where += ' AND h.changed_at >= CAST(:startDate AS date)';
        params.startDate = startDate;
      }
      if (endDate !== null) {
        where += ' AND h.changed_at < CAST(:endDate AS date) + 1';
        params.endDate = endDate;
      }
      if (employeeId !== null) {
        where += ' AND l.employee_id = CAST(:employeeId AS bigint)';
        params.employeeId = employeeId;
      }
      const from =
        ' FROM annual_leave_history h JOIN annual_leave l ON l.annual_leave_id = h.annual_leave_id ';
      const countRows = await db.query(
        'SELECT COUNT(*) AS "total"' + from + where,
        params,
      );
      const total = Number(countRows[0]?.total ?? 0);
      const rows = await db.query(
        'SELECT h.annual_leave_history_id AS "annualLeaveHistoryId",' +
          ' h.changed_at AS "changedAt",' +
          ' h.changer_id AS "changerId",' +
          ' h.change_type AS "changeType",' +
          ' h.change_days AS "changeDays",' +
          ' h.change_content AS "changeContent"' +
          from +
          where +
          ' ORDER BY h.changed_at DESC, h.annual_leave_history_id DESC' +
          ' LIMIT :limit OFFSET :offset',
        { ...params, limit, offset: page * limit },
      );
      const items = rows.map((r: any) => ({
        annualLeaveHistoryId: Number(r.annualLeaveHistoryId),
        changedAt: r.changedAt,
        changerId: r.changerId === null ? null : Number(r.changerId),
        changeType: r.changeType,
        changeDays: Number(r.changeDays),
        changeContent: r.changeContent,
      }));
      return { items, page, size: limit, total };
    });
  }
}

