import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  ErrorText,
  Field,
  Filters,
  LookupSelect,
  Num,
  Pager,
  Pairs,
  RefName,
  Tiles,
  call,
  useData,
} from '../kit';
import type { Column, Page, PageProps, Row } from '../kit';

const PAGE_SIZE = 20;

export default function FnSfr01904Page({ role, notify }: PageProps) {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);

  const { data, error, loading } = useData<Page>(
    () =>
      call<Page>('GET', '/annual-leave-histories', role, undefined, {
        ...applied,
        page,
        size: PAGE_SIZE,
      }),
    [applied, page, role],
  );

  const search = () => {
    if (startDate && endDate && startDate > endDate) {
      notify('조회 시작일이 종료일보다 늦을 수 없습니다.');
      return;
    }
    setPage(0);
    setApplied({ startDate, endDate, employeeId });
  };

  const reset = () => {
    setStartDate('');
    setEndDate('');
    setEmployeeId('');
    setPage(0);
    setApplied({});
  };

  const columns: Column[] = [
    { key: 'changedAt', label: '변경 일시', render: (r) => <DateText value={r.changedAt} time /> },
    {
      key: 'changerId',
      label: '변경자',
      render: (r) =>
        r.changerId ? <RefName table="employee" role={role} value={r.changerId} /> : <span>시스템</span>,
    },
    { key: 'changeType', label: '변경 유형', render: (r) => <Badge value={r.changeType} /> },
    { key: 'changeDays', label: '변경 일수', render: (r) => <Num value={r.changeDays} /> },
    { key: 'changeContent', label: '변경 내용' },
  ];

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>조회 건수</h2>
        <Tiles items={[['변경이력', <Num value={data?.total ?? 0} />]]} />
      </section>
      <section className="box span-8">
        <h2>변경이력 조회 조건</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="변경 일시 조회 시작">
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="변경 일시 조회 종료">
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
          <Field label="대상 임직원">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
          </Field>
        </Filters>
      </section>
      <section className="box span-12">
        <h2>연차 변경이력</h2>
        <Band total={data?.total} />
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          columns={columns}
          rows={data?.items ?? []}
          onRowClick={(row) => setSelected(row)}
          empty={loading ? '불러오는 중입니다.' : '조회된 변경이력이 없습니다.'}
        />
        <Pager page={page} size={PAGE_SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>
      {selected ? (
        <Drawer title="연차 변경이력 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['연차 변경이력 ID', String(selected.annualLeaveHistoryId ?? '')],
              ['변경 일시', <DateText value={selected.changedAt} time />],
              [
                '변경자',
                selected.changerId ? (
                  <RefName table="employee" role={role} value={selected.changerId} />
                ) : (
                  '시스템'
                ),
              ],
              ['변경 유형', <Badge value={selected.changeType} />],
              ['변경 일수', <Num value={selected.changeDays} />],
              ['변경 내용', String(selected.changeContent ?? '')],
            ]}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
